/**
 * @method
 * @name kospiYn
 * @description desc
 * @param {string} kospiyn desc
 * @param {string} isu_nm desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.kospiYn = function(kospiyn, isu_nm) {
    if (kospiyn != 'Y') {
        alert(isu_nm + "은(는) KOSPI200 또는 KOSDAQ150 종목이 아니므로 신청하실수 없습니다.");
        return false;
    }
    return true;
};


