/*2010.06
	  권리형태, 권리유형값에 따라  조기종료평가가격/지수 항목 값 셋팅
	*/
/**
 * @method
 * @name setElwKoValuPrcMethd
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setElwKoValuPrcMethd = function() {
    form.elwKoValuPrcMethd.style.setStyle("backgroundcolor", '#D9D9D9');
    form.elwKoValuPrcMethd.setReadOnly(true);
    form.elwKoValuPrcMethd.setValue("");
    if (form.elwRghtTpKindCd.getValue() == "3") {
        // 조기종료형
        if (form.elwRghtTpCd.getValue() == "C") {
            //콜
            form.elwKoValuPrcMethd.setValue("12시전 조기종료이벤트 발생시 조기종료발생시점이후부터 당일 장종료시점까지의 기초자산 체결가격 중 가장 낮은 가격 이상, 12시이후 조기종료이벤트 발생시 조기종료발생시점이후부터 익일 12시전까지의 기초자산 체결가격 중 가장 낮은 가격 이상");
        } else if (form.elwRghtTpCd.getValue() == "P") {
            //풋

            form.elwKoValuPrcMethd.setValue("12시전 조기종료이벤트 발생시 조기종료발생시점이후부터 당일 장종료시점까지의 기초자산 체결가격 중 가장 높은 가격 이하, 12시이후 조기종료이벤트 발생시 조기종료발생시점이후부터 익일 12시전까지의 기초자산 체결가격 중 가장 높은 가격 이하");
        }
    }
    /* 2010.08.25 삭제요청
	       else { // 표준형,디지털형 
	           form.elwKoValuPrcMethd.value = "해당사항 없음";
	       } */
};



