    	} else if (form.elwRghtTpCd.value == "P") {	//풋
	        form.elwExerContn.value = "만기평가가격이 행사가격 미만인 경우, 1워런트당 (행사가격-만기평가가격)*전환비율";	        
    	} else {
    		form.elwExerContn.value = "해당사항 없음";
        }    
    } else { // 디지털형 
        if (form.elwRghtTpCd.value == "C") {	//콜
	        form.elwExerContn.value = "만기평가가격이 행사가격 이상인 경우 확정지급액 지급";	        
    	} else if (form.elwRghtTpCd.value == "P") {	//풋
	        form.elwExerContn.value = "만기평가가격이 행사가격 이하인 경우 확정지급액 지급";	        
    	} else {
    		form.elwExerContn.value = "해당사항 없음";
