/*2010.06
	  권리형태에 따라  조기종료시권리내용 항목 값 셋팅
	*/
/**
 * @method
 * @name setElwKoExerContn
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setElwKoExerContn = function() {
    var strElwKoExerContn;
    var strElwCompnsRt = form.elwCompnsRt.getValue(); //최소지급비율
    var strElwRghtTpCd = form.elwRghtTpCd.getValue(); //권리유형

    form.elwKoExerContn.setReadOnly(false);
    if (form.elwRghtTpKindCd.getValue() == "3") {
        // 조기종료형
        //form.elwKoExerContn.value = "";
        form.elwKoExerContn.setReadOnly(true);
        form.elwKoExerContn.style.setStyle("backgroundcolor", '#FFFFFF');

        //2010.10 추가
        if (strElwCompnsRt != null && strElwCompnsRt != "") {
            if (strElwRghtTpCd == "C") {
                // 콜		
                strElwKoExerContn = "MAX[(조기종료평가가격-행사가격),(조기종료발생기준가격-행사가격)*" + strElwCompnsRt + "%]*전환비율";
            } else if (strElwRghtTpCd == "P") {
                // 풋		
                strElwKoExerContn = "MAX[(행사가격-조기종료평가가격),(행사가격-조기종료발생기준가격)*" + strElwCompnsRt + "%]*전환비율";
            }
            form.elwKoExerContn.setValue(strElwKoExerContn);
        } else {
            form.elwKoExerContn.setValue("");
        }
    } else {
        // 표준형, 디지털형 
        form.elwKoExerContn.setValue("");
        form.elwKoExerContn.setReadOnly(true);
        form.elwKoExerContn.style.setStyle("backgroundcolor", '#D9D9D9');
    }
};




/*2010.07
	  권리형태에 따라  조기종료발생기준가격/지수 항목 상태 셋팅
	*/
/**
 * @method
 * @name setElwKoBasPrc
