        form.elwKoBasPrc.setReadOnly(true);
        form.elwKoBasPrc.style.setStyle("backgroundcolor", '#D9D9D9');
    }
};




/*
	   기초자산별로 만기평가가격/지수 셋팅(2010.08.25)
	  param: 기존에 저장한 내용
	*/
/**
 * @method
 * @name setElwExpValuPrcMethd
 * @description desc
 * @param {string} val1 desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setElwExpValuPrcMethd = function(val1) {
    var isuAbbrv3 = form.isuAbbrv3.getValue(); //기초자산

    if (val1 == "") {
        if (isuAbbrv3 == "KOSPI200") {
            //KOSPI200 지수인 경우
            form.elwExpValuPrcMethd.setValue("최종거래일 종가");
        } else {
            //기초자산이 개별종목인 경우
            form.elwExpValuPrcMethd.setValue("최종거래일포함 직전 5영업일 종가의 산술평균");
        }
    } else {
        form.elwExpValuPrcMethd.setValue(val1);
    }
};




