/**
 * @method
 * @name fn_IsuCheckValues
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_IsuCheckValues = function() {
    if (form.sysdate.getValue() >= form.expDd.getValue()) {
        alert("만기일을 현재일이후로 입력해 주십시오.");
        form.expDd.focus();
        return;
    }
    if (form.sysdate.getValue() >= form.exerStrtDd.getValue()) {
        alert("행사시작일을 현재일이후로 입력해 주십시오.");
        form.exerStrtDd.focus();
        return;
    }
    if (form.sysdate.getValue() >= form.exerEndDd.getValue()) {
        alert("행사종료일을 현재일이후로 입력해 주십시오.");
        form.exerEndDd.focus();
        return;
    }
    if (form.sysdate.getValue() >= form.elwLsttrdDd.getValue()) {
        alert("최종거래일을 현재일이후로 입력해 주십시오.");
        form.elwLsttrdDd.focus();
        return;
    }
    if (form.elwLsttrdDd.getValue() >= form.exerStrtDd.getValue()) {
        alert("행사시작일을 최종거래일이후로 입력해 주십시오.");
        form.exerStrtDd.focus();
        return;
    }
    if (form.elwLsttrdDd.getValue() >= form.exerEndDd.getValue()) {
        alert("행사종료일을 최종거래일이후로 입력해 주십시오.");
        form.exerEndDd.focus();
        return;
    }
    if (form.sysdate.getValue() >= form.elwPayDd.getValue()) {
        alert("지급일을 현재일이후로 입력해 주십시오.");
        form.elwPayDd.focus();
        return;
    }
    if (form.elwLsttrdDd.getValue() >= form.elwPayDd.getValue()) {
        alert("지급일을 최종거래일 이후로 입력해 주십시오.");
        form.elwPayDd.focus();
        return;
    }
    if (getByteLength(form.elwExerContn.getValue()) > 100) {
        alert("권리내용을 100byte 이내로 입력해 주십시오.");
        form.elwExerContn.focus();
        return false;
    }
    if (getByteLength(form.elwExpValuPrcMethd.getValue()) > 100) {
        alert("만기시지급조건을 100byte 이내로 입력해 주십시오.");
        form.elwExpValuPrcMethd.focus();
        return false;
    }
    if (getByteLength(form.delisttmPayCondContn.getValue()) > 200) {
        alert("상장폐지시지급조건을 100자 이내로 입력해 주십시오.");
        form.delisttmPayCondContn.focus();
        return false;
    }
    if (getByteLength(form.elwPayAgntNm.getValue()) > 80) {
        alert("지급대리인을 40자 이내로 입력해 주십시오.");
        form.elwPayAgntNm.focus();
        return false;
    }


    // ELW권리형태종류코드 관련 체크 
    if (form.elwRghtTpKindCd.getValue() == '2') {
        if (getByteLength(form.elwFinalPayVal.getValue()) == 0) {
            alert("권리형태가 디지털형이면 확정지급액을 입력해 주십시오.");
            form.elwFinalPayVal.focus();
            return;
        }
    } else {
        if (getByteLength(form.elwFinalPayVal.getValue()) > 0) {
            alert("확정지급액은 권리형태가 디지털형일때만 입력합니다.");
            form.elwFinalPayVal.focus();
            return;
        }
    }

    // ELW권리행사유형코드
    // 권리행사방식이 유럽형일때만 체크해야됨..
    if (form.elwExerTpCd.getValue() == 'E') {
        // 유럽형

        if (form.exerStrtDd.getValue() != form.exerEndDd.getValue()) {
            alert("행사시작일과 행사종료일을 동일하게 입력해 주십시오.");
            form.exerStrtDd.focus();
            return;
        }
        if (form.exerStrtDd.getValue() != form.expDd.getValue()) {
            alert("행사시작일과 만기일을 동일하게 입력해 주십시오.");
            form.exerStrtDd.focus();
            return;
        }
    }


    // LP Check
    if (!scwin.LpCheckValues(0)) {
        return false;
    }
    if (getByteLength(form.lpMbrNo[1].getValue()) > 0) {
        if (!scwin.LpCheckValues(1)) {
            return false;
        }
    }
    if (getByteLength(form.lpMbrNo[2].getValue()) > 0) {
        if (!scwin.LpCheckValues(2)) {
            return false;
        }
    }
    if (!scwin.fn_ulyCheck()) return false;
    return true;
};
/**
 * @method
 * @name LpCheckValues
 * @description desc
 * @param {string} idx desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.LpCheckValues = function(idx) {
    var count = eval(idx) + 1;
    if (getByteLength(form["lpMbrNo"][idx].getValue()) == 0) {
        alert("유동성공급자_" + count + "을 입력해 주십시오.");
        form["lpMbrNo"][idx].focus();
        return false;
    }
    if (getByteLength(form["lpContrtDd"][idx].getValue()) == 0) {
        alert("유동성공급계약일_" + count + "을 입력해 주십시오.");
        form["lpContrtDd"][idx].focus();
        return false;
    }
    if (getByteLength(form["lpStrtDd"][idx].getValue()) == 0) {
        alert("유동성공급기간_" + count + "을 입력해 주십시오.");
        form["lpStrtDd"][idx].focus();
        return false;
    }
    if (form.sysdate.getValue() >= form["lpStrtDd"][idx].getValue()) {
        alert("유동성공급기간_" + count + "을 현재일이후로 입력해 주십시오.");
        form["lpStrtDd"][idx].focus();
        return;
    }
    if (getByteLength(form["lpEndDd"][idx].getValue()) == 0) {
        alert("유동성공급기간_" + count + "을 입력해 주십시오.");
        form["lpEndDd"][idx].focus();
        return false;
    }
    if (form.sysdate.getValue() >= form["lpEndDd"][idx].getValue()) {
        alert("유동성공급기간_" + count + "을 현재일이후로 입력해 주십시오.");
        form["lpEndDd"][idx].focus();
        return;
    }
    if (form["lpStrtDd"][idx].getValue() >= form["lpEndDd"][idx].getValue()) {
        alert("유동성공급기간_" + count + "의 시작일을 종료일이전으로  입력해 주십시오.");
        form["lpStrtDd"][idx].focus();
        return;
    }
    return true;
};


// 기초자산관련 체크
/**
 * @method
 * @name fn_ulyCheck
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_ulyCheck = function() {
    // 주식
    if (form.fncUlyTpCd.getValue() == '1') {
        if (getByteLength(form.ulyIsuCd[0].getValue()) == 0) {
            alert("기초자산이 '주식'일 경우 해당 '주권발행기관_1'를 선택해 주십시오.");
            form.ulyIsuCd[0].focus();
            return false;
        } else {
            if (!scwin.kospiYn(form.kospiYn[0].getValue(), form.ulyIsuNm[0].getValue())) {
                return false;
            }
        }
        if (getByteLength(form.ulyCompstRto[0].getValue()) == 0) {
            //alert("기초자산이 '주식'일 경우 해당 '주권발행기관 구성주식수_1'를 입력해 주십시오.");
            form.ulyCompstRto[0].focus();
            //return false;

        }

        // 주식바스켓

    } else if (form.fncUlyTpCd.getValue() == '2') {
        if (getByteLength(form.ulyIsuCd[0].getValue()) == 0 || getByteLength(form.ulyIsuCd[1].getValue()) == 0) {
            alert("기초자산이 '주식바스켓'일 경우 해당 '주권발행기관'를 최대5개를 선택해 주십시오.");
            form.ulyIsuNm[0].focus();
            return false;
        }
        if (!scwin.kospiYn(form.kospiYn[0].getValue(), form.ulyIsuNm[0].getValue())) {
            return false;
        }
        if (!scwin.kospiYn(form.kospiYn[1].getValue(), form.ulyIsuNm[1].getValue())) {
            return false;
        }
        if (getByteLength(form.ulyCompstRto[0].getValue()) == 0) {
            alert("'주권발행기관 구성주식수_1'를 입력해 주십시오.");
            form.ulyCompstRto[0].focus();
            return false;
        }
        if (getByteLength(form.ulyCompstRto[1].getValue()) == 0) {
            alert("'주권발행기관 구성주식수_2'를 입력해 주십시오.");
            form.ulyCompstRto[1].focus();
            return false;
        }
        if (getByteLength(form.ulyIsuCd[2].getValue()) > 0) {
            if (!scwin.kospiYn(form.kospiYn[2].getValue(), form.ulyIsuNm[2].getValue())) {
                return false;
            }
            if (getByteLength(form.ulyCompstRto[2].getValue()) == 0) {
                alert("'주권발행기관 구성주식수_3'를 입력해 주십시오.");
                form.ulyCompstRto[2].focus();
                return false;
            }
        }
        if (getByteLength(form.ef_bs_ass_4.getValue()) > 0) {
            if (!scwin.kospiYn(form.kospiYn[3].getValue(), form.ulyIsuNm[3].getValue())) {
                return false;
            }
            if (getByteLength(form.ulyCompstRto[3].getValue()) == 0) {
                alert("'주권발행기관 구성주식수_4'를 입력해 주십시오.");
                form.ulyCompstRto[3].focus();
                return false;
            }
        }
        if (getByteLength(form.ef_bs_ass_5.getValue()) > 0) {
            if (!scwin.kospiYn(form.kospiYn[4].getValue(), form.ulyIsuNm[4].getValue())) {
                return false;
            }
            if (getByteLength(form.ulyCompstRto[4].getValue()) == 0) {
                alert("'주권발행기관 구성주식수_5'를 입력해 주십시오.");
                form.ulyCompstRto[4].focus();
                return false;
            }
        }


        // 지수

    } else if (form.fncUlyTpCd.getValue() == '3') {
        if (getByteLength(form.elwObjIdxTpCd.getValue()) == 0) {
            alert("기초자산이 '지수'일 경우 주가지수를 선택해 주십시오.");
            form.elwObjIdxTpCd.focus();
            return false;
        }
    }
    if (form.fncUlyTpCd.options[1].selected || form.fncUlyTpCd.options[3].selected) {
        if (form.ulyCompstRto[0].getValue() != '1') {
            //alert("기초자산이 '주식' 또는 '지수'일 경우는 '주권발행기관 구성주식수_1'을 1로 입력해 주십시오.");
            form.ulyCompstRto[0].focus();
            //return false;

        }
    }
    return true;
};
