/* 최소지급비율에 따라 조기종료시 권리내용 setting  */
/**
 * @method
 * @name fn_setElwKoExerContnByRghtTpCd
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_setElwKoExerContnByRghtTpCd = function() {
    var strElwKoExerContn;
    var strElwCompnsRt = form.elwCompnsRt.getValue(); //최소지급비율
    var strElwRghtTpCd = form.elwRghtTpCd.getValue(); //권리유형
    var strElwRghtTpKindCd = form.elwRghtTpKindCd.getValue(); //권리형태


    if (strElwRghtTpKindCd == "3") {
        // 조기종료형
        if (strElwCompnsRt != null && strElwCompnsRt != "") {
            if (strElwRghtTpCd == "C") {
                // 콜		
                strElwKoExerContn = "MAX[(조기종료평가가격-행사가격),(조기종료발생기준가격-행사가격)*" + strElwCompnsRt + "%]*전환비율";
            } else if (strElwRghtTpCd == "P") {
                // 풋		
                strElwKoExerContn = "MAX[(행사가격-조기종료평가가격),(행사가격-조기종료발생기준가격)*" + strElwCompnsRt + "%]*전환비율";
            }
            form.elwKoExerContn.setValue(strElwKoExerContn);
        } else {
            form.elwKoExerContn.setValue("");
        }
    }
};
